+
+void octave_window_store(torch::Tensor key, torch::Tensor value,
+                         torch::Tensor slot_mapping, torch::Tensor positions,
+                         torch::Tensor wtab, torch::Tensor wtags,
+                         torch::Tensor wlocks, torch::Tensor stab,
