+// ===========================================================================
+// Phase 1: prefix
+// ===========================================================================
+constexpr int NW = 8;         // compute wave pairs (16 query vectors each)
+constexpr int NL = 8;         // loader waves
+constexpr int KROW = D + 16;  // bytes per K row in LDS
+constexpr float PSCALE = 4096.0f;
